/** The OpenAPI document (api/openapi.json, generated by scripts/gen_openapi.mjs) and the small helpers the reference page needs. */
import raw from '../../../../api/openapi.json';

export interface Schema {
  $ref?: string;
  type?: string;
  description?: string;
  properties?: Record<string, Schema>;
  required?: string[];
  items?: Schema;
  enum?: unknown[];
  const?: unknown;
  default?: unknown;
  minimum?: number;
  maximum?: number;
  minLength?: number;
  maxLength?: number;
  minItems?: number;
  maxItems?: number;
  uniqueItems?: boolean;
  pattern?: string;
  format?: string;
  examples?: unknown[];
  additionalProperties?: boolean | Schema;
}

export interface ExampleObject {
  summary?: string;
  description?: string;
  value: unknown;
  'x-expected-status'?: number;
}
export interface MediaType {
  schema: Schema;
  examples?: Record<string, ExampleObject>;
}
export interface ResponseObject {
  description: string;
  content?: Record<string, MediaType>;
}
export interface OperationObject {
  operationId: string;
  tags: string[];
  summary: string;
  description?: string;
  requestBody?: { required?: boolean; content: Record<string, MediaType> };
  responses: Record<string, ResponseObject>;
}
export interface OpenApiDoc {
  openapi: string;
  info: { title: string; version: string; summary?: string; description?: string };
  servers: { url: string; description?: string }[];
  tags: { name: string; description?: string }[];
  paths: Record<string, Partial<Record<'get' | 'post', OperationObject>>>;
  components: { schemas: Record<string, Schema> };
}

export const doc = raw as unknown as OpenApiDoc;

export interface Operation {
  method: 'GET' | 'POST';
  path: string;
  tag: string;
  op: OperationObject;
  /** Deep-link id, e.g. `operation-postcalculate`. */
  anchor: string;
}

export const operationAnchor = (method: string, path: string) => `operation-${method}${path}`.toLowerCase().replace(/[^a-z0-9-]/g, '');
export const schemaAnchor = (name: string) => `schema-${name}`;

/** Every operation, in the order of `tags` and then of `paths`. */
export function listOperations(d: OpenApiDoc = doc): Operation[] {
  const all: Operation[] = [];
  for (const [path, item] of Object.entries(d.paths)) {
    for (const method of ['get', 'post'] as const) {
      const op = item[method];
      if (op) all.push({ method: method.toUpperCase() as Operation['method'], path, tag: op.tags[0] ?? 'Other', op, anchor: operationAnchor(method, path) });
    }
  }
  const rank = (t: string) => d.tags.findIndex((x) => x.name === t);
  return all.sort((a, b) => rank(a.tag) - rank(b.tag));
}

export const SCHEMA_NAMES = Object.keys(doc.components.schemas);

export const refName = (ref: string | undefined): string | null => (ref?.startsWith('#/components/schemas/') ? ref.slice('#/components/schemas/'.length) : null);

/** Follow a `$ref`; keys next to the `$ref` (a field-specific description) win over the target's. */
export function resolve(s: Schema, d: OpenApiDoc = doc): Schema {
  const name = refName(s.$ref);
  if (!name) return s;
  const { $ref: _ref, ...own } = s;
  void _ref;
  return { ...(d.components.schemas[name] ?? {}), ...own };
}

/** Child schemas shown when a node is expanded: object properties, or the properties of array items. */
export function childrenOf(s: Schema): { schema: Schema; required: string[] } | null {
  const r = resolve(s);
  if (r.properties) return { schema: r, required: r.required ?? [] };
  if (r.type === 'array' && r.items) {
    const item = resolve(r.items);
    if (item.properties) return { schema: item, required: item.required ?? [] };
  }
  return null;
}

/** "integer", "string[]", "object" ... plus the model name when the schema is a reference. */
export function typeLabel(s: Schema): { type: string; ref: string | null; itemRef: string | null } {
  const ref = refName(s.$ref);
  const r = resolve(s);
  if (r.type === 'array') {
    const it = r.items ? resolve(r.items) : null;
    const itemRef = r.items ? refName(r.items.$ref) : null;
    return { type: `array of ${itemRef ?? it?.type ?? 'any'}`, ref, itemRef };
  }
  if (r.type) return { type: r.type, ref, itemRef: null };
  if (r.enum) return { type: 'enum', ref, itemRef: null };
  if (r.const !== undefined) return { type: typeof r.const, ref, itemRef: null };
  return { type: 'any', ref, itemRef: null };
}

const fmt = (n: number) => (Math.abs(n) >= 1e6 ? n.toExponential().replace('e+', 'e') : String(n));

/** Constraint chips: min/max/length/items/pattern/format/const. Defaults and enums are shown separately. */
export function constraintsOf(s: Schema): string[] {
  const r = resolve(s);
  const out: string[] = [];
  if (r.const !== undefined) out.push(`const ${JSON.stringify(r.const)}`);
  if (r.format) out.push(`format ${r.format}`);
  if (r.minimum !== undefined) out.push(`min ${fmt(r.minimum)}`);
  if (r.maximum !== undefined) out.push(`max ${fmt(r.maximum)}`);
  if (r.minLength !== undefined) out.push(`minLength ${r.minLength}`);
  if (r.maxLength !== undefined) out.push(`maxLength ${r.maxLength}`);
  const items = r.items ? resolve(r.items) : null;
  if (r.minItems !== undefined) out.push(`minItems ${r.minItems}`);
  if (r.maxItems !== undefined) out.push(`maxItems ${r.maxItems}`);
  if (r.uniqueItems) out.push('unique items');
  if (r.pattern) out.push(`pattern ${r.pattern}`);
  if (items?.enum && !r.enum) out.push(`items: ${items.enum.length} values`);
  return out;
}

export const baseUrl = (): string => (import.meta.env.VITE_API_URL ?? 'http://localhost:8080').replace(/\/+$/, '');

const sq = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;

/** curl command for a JSON request; `body` undefined means no body (GET). */
export function curlSnippet(base: string, method: string, path: string, body?: unknown): string {
  const lines = [`curl -X ${method} ${base}${path}`];
  if (body !== undefined) {
    lines.push(`  -H 'Content-Type: application/json'`);
    lines.push(`  -d ${sq(JSON.stringify(body))}`);
  }
  return lines.join(' \\\n');
}

/** fetch() call for the same request. */
export function fetchSnippet(base: string, method: string, path: string, body?: unknown): string {
  if (body === undefined) return `const res = await fetch('${base}${path}');\nconsole.log(res.status, await res.json());`;
  return [
    `const res = await fetch('${base}${path}', {`,
    `  method: '${method}',`,
    `  headers: { 'Content-Type': 'application/json' },`,
    `  body: JSON.stringify(${JSON.stringify(body, null, 2).replace(/\n/g, '\n  ')}),`,
    `});`,
    `console.log(res.status, await res.json());`,
  ].join('\n');
}
